			let a = map(i, 0, 12, 0, TAU);
			let r = this.w * 0.45
			line(r * cos(a), r * sin(a), r * 0.9 * cos(a), r * 0.9 * sin(a));
		}

		let ang = noise(this.t / 300) * this.gc;
		noFill();
		strokeWeight(this.w / 200);
		this.col.setAlpha(255);
		stroke(this.col);
		this.col.setAlpha(100);
