		vertex(this.w * 0.05 * cos(ang - PI / 2), this.w * 0.05 * sin(ang - PI / 2));
		endShape(CLOSE);
		this.col.setAlpha(255);
		fill(this.col);
		circle(0, 0, this.w * 0.02);
		pop();
	}

	move() {
		this.t += this.tStep;
	}

	run() {
		this.show();
		this.move();
